#include "physics/OriginalVehiclePhysics.h"
#include "OriginalGameCar.h"
#include <fstream>
#include <iostream>
#include <cstring>
#include <stdexcept>
namespace P=r3d::physics;namespace G=r3d::game::originalrace::source;
static float value(unsigned u){float v;std::memcpy(&v,&u,4);return v;}
static unsigned word(float v){unsigned u;std::memcpy(&u,&v,4);return u;}
static void vec(std::ostream&o,P::Vec3 v){o<<'['<<word(v.x)<<','<<word(v.y)<<','<<word(v.z)<<']';}
static void quat(std::ostream&o,P::Quat q){o<<'['<<word(q.x)<<','<<word(q.y)<<','<<word(q.z)<<','<<word(q.w)<<']';}
int main(int argc,char**argv){try{if(argc!=3)return 2;std::ifstream in(argv[1]);std::ofstream out(argv[2]);if(!in||!out)throw std::runtime_error("Cannot open fixture/output");unsigned id,contact,u;
while(in>>id>>contact){float x[8];for(auto&v:x){if(!(in>>u))throw std::runtime_error("Truncated fixture");v=value(u);}P::WorldDescription d;d.gravity=x[1];d.includeDeathPlane=false;d.startPosition={0,0,5};auto&v=d.vehicle;v.mass=x[0];v.halfExtents={1,1,.25F};v.bodyLinearDamping=v.bodyAngularDamping=0;v.bodySleepEnergyThreshold=1;v.differentialRatio=3.42F;v.idlingRpm=1000;v.maximumRpm=7000;v.wheelContactsEnabled=false;v.maximumTorque=v.restBrakeTorque=v.brakeTorque=0;
for(int i=0;i<4;++i){P::WheelDescription w;w.position={i<2?1.F:-1.F,i%2?1.F:-1.F,-.5F};w.radius=.5F;w.width=.2F;w.suspensionTravel=.4F;w.inverseMass=1;w.flags=0;w.longitudinalTire={1.F,.02F,2.F,.01F,0.F};w.lateralTire=w.longitudinalTire;w.driven=w.steering=i<2;v.wheels.push_back(w);}
P::TriangleMesh floor;floor.vertices={{-500,-500,-1000},{500,-500,-1000},{500,500,-1000},{-500,500,-1000}};floor.indices={0,1,2,0,2,3};d.collisionMeshes.push_back(floor);std::string error;auto world=P::createOriginalVehicleWorld(d,error);if(!world)throw std::runtime_error(error);
world->addLinearVelocity(0,{x[2],x[3],x[4]});world->setAngularMomentum(0,{0,0,0}); // Zero initial omega and refresh public cached state for input validation.
auto before=world->vehicle();G::GameCar car;G::GameCar::MotorDescription motor;motor.maximumTorque=motor.brakeTorque=motor.restBrakeTorque=0;car.ConfigureMotor(motor);G::GameCar::DynamicsDescription dynamics;dynamics.angularDamping={{1,1,1}};dynamics.airbornePitchAcceleration=x[5];car.ConfigureDynamics(dynamics,{});car.BindWheels(std::vector<bool>(4,false),std::vector<bool>(4,false));if(x[6]!=0){if(x[6]!=1.5F)throw std::runtime_error("Only public LockSpring initial state allowed");car.LockSpring();}unsigned callbacks=0;G::GameCar::DriveCommand drive;float horizontalSpeed=0;
world->setVehicleFixedStepController([&](std::size_t,float,const P::VehicleInput&,const P::VehicleFixedStepState& st){++callbacks;horizontalSpeed=st.horizontalSpeed;G::GameCar::FixedStepState incoming;incoming.anyWheelContact=contact!=0;incoming.horizontalSpeed=st.horizontalSpeed;drive=car.OnFixedStepDrive(x[7],{},incoming);P::VehicleDriveCommand cmd;cmd.applyAngularStabilization=false;cmd.originalGameCarJump=true;cmd.applyExtraGravity=drive.applyExtraGravity;cmd.airbornePitchAcceleration=drive.airbornePitchAcceleration;return cmd;});
world->step(1.F/60,P::VehicleInput{});auto after=world->vehicle();if(callbacks!=1)throw std::runtime_error("Expected one game callback");out<<"{\"event\":\"jump.sample\",\"case\":"<<id<<",\"callbacks\":"<<callbacks<<",\"contact\":"<<(contact?"true":"false")<<",\"spring_after_word\":"<<word(car.GetSpringTime())<<",\"velocity_before\":";vec(out,before.linearVelocity);out<<",\"rotation_before\":";quat(out,before.body.rotation);out<<",\"horizontal_speed_word\":"<<word(horizontalSpeed)<<",\"applied_extra_gravity\":"<<(drive.applyExtraGravity?"true":"false")<<",\"applied_pitch_word\":"<<word(drive.airbornePitchAcceleration)<<",\"position_after_step\":";vec(out,after.body.position);out<<",\"velocity_after_step\":";vec(out,after.linearVelocity);out<<",\"rotation_after_step\":";quat(out,after.body.rotation);out<<",\"momentum_after_step\":";vec(out,after.angularMomentum);out<<",\"awake_after_step\":"<<(after.bodyAwake?"true":"false")<<"}\n";
}if(!in.eof())throw std::runtime_error("Invalid fixture tail");return out.good()?0:4;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 3;}}
